// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(uint256 dummy) public {
        // The general invariant: owner() must return a non-zero address,
        // because the contract is constructed with a non-zero owner and ownership is never renounced.
        // The bug makes owner() always return address(0), so this assertion fails on every input.
        address own = c.owner();
        assertTrue(own != address(0));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address fuzzedOwner) public {
        // For any non-zero fuzzedOwner, the owner() should equal fuzzedOwner after transferring ownership to it.
        // The buggy version always returns address(0), so the equality will fail.
        vm.assume(fuzzedOwner != address(0));
        vm.prank(c.owner());
        c.transferOwnership(fuzzedOwner);
        assertEq(c.owner(), fuzzedOwner);
    }
}

