pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        vm.assume(caller != newOwner);

        // Transfer ownership to newOwner
        c.transferOwnership(newOwner);

        // Capture the original owner (deployer = address(this))
        address originalOwner = c.owner();
        assertEq(originalOwner, newOwner, "ownership transfer failed setup");

        // Now from caller's perspective, call owner()
        vm.prank(caller);
        address reportedOwnerByCaller = c.owner();

        // The property: owner() must always return the stored owner (newOwner), regardless of caller.
        // The buggy contract would return msg.sender (caller) when queried from a non-owner.
        assertEq(reportedOwnerByCaller, newOwner);
    }
}

