// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address newOwner) public {
        // 1. Assume newOwner is not the zero address initially (the bug is about allowing zero *after* call)
        //    But we must allow zero address as input because the fuzzer should find that zero triggers the bug.
        //    However, the original transferOwnership requires newOwner != address(0).
        //    So we must ensure newOwner as a fuzzed input can be zero.
        //    We don't need to bound it; zero address is a valid address for the fuzzer.

        // 2. We need to be the current owner to call transferOwnership.
        //    In setUp() we deployed C with address(this) as initial _liquidityReceiveAddress.
        //    The constructor of C mints to _msgSender() which is this test contract.
        //    The initial owner is this test contract, so we can call transferOwnership.

        // 3. Call transferOwnership with the fuzzed newOwner. If it reverts, catch to see the outcome.
        bool success;
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }

        // 4. GENERAL RULE: if the call succeeded, then owner() must NOT be address(0).
        //    The reference always either reverts (if newOwner is address(0)) or succeeds with a non-zero owner.
        //    The buggy version succeeds even with address(0) as newOwner, making owner() == address(0).
        assertTrue(!success || c.owner() != address(0));
    }
}

