        // Actually, we can use the initial supply which was minted to msg.sender (which is address(this) in setUp).
        // We'll transfer from address(this) to account.
        // The amount is the change in the internal _balances mapping.
        uint256 initialBalance = c.balanceOf(account);
        // Transfer from address(this) (who has balance) to account.
        // Since address(this) is the deployer and minted initial supply, it has sufficient balance.
        vm.prank(address(this));
        c.transfer(account, amount);
        uint256 finalBalance = c.balanceOf(account);
        // 3. The invariant: the change in balanceOf must equal the transferred amount.
        // In the reference, finalBalance == initialBalance + amount.
        // In the mutant, finalBalance == initialBalance + 2*amount.
        assertTrue(finalBalance == initialBalance + amount);
    }
}

